/**
 * Sonda de caza 0.1.97 — MATRIZ DE DOMINIOS, PARTE A (eje «matriz»).
 * 16 preguntas (4 dominios x 4), condiciones a/b/d en rotacion completa,
 * f sin fuentes en 4 preguntas, y formas F-01..F-12 del segundo
 * refinamiento. Un caso en rojo = hallazgo contra el juez, no error de
 * fixture: cada cifra inventada (iii/v/vi-a) no aparece en ningun chunk
 * del caso y cada cifra lavada (iv) solo aparece, fuera de la guia, en
 * el chunk de ruido nombrado en la nota (en condicion a, sin ruido, la
 * cifra se lava desde un dato secundario de la propia guia).
 */
import { describe, expect, it, afterAll } from "vitest";
import { writeFileSync } from "node:fs";
import { verifyGroundedAnswer, type GroundingChunk } from "./grounding";

interface CasoCaza {
  id: string;
  eje: string;
  dominio: string;
  pregunta: string;
  idioma: "es" | "en" | "pt";
  condicion: string;
  mutacion: string;
  forma: string | null;
  fuentes: GroundingChunk[];
  respuesta: string;
  esperado: "conserva" | "corta" | "contrato-skipped";
  marcador: string;
  nota?: string;
}

interface ResultadoCaza extends CasoCaza {
  obtenido: { status: string; removed: number; kept: number; marcadorPresente: boolean; payloadPresente?: boolean };
  pasa: boolean;
}
const RESULTADOS: ResultadoCaza[] = [];


/**
 * RESIDUO DECLARADO de la caza 0.1.97 (medido, no escondido): los
 * casos que el juez determinista no puede cazar sin traducción
 * automática — la invención en otro idioma sin cifras ni datos que
 * la delaten (condición d sin datos), las fechas nombradas cruzadas
 * y la polisemia fina. Van con it.fails ESTRICTO: si un caso del
 * residuo empieza a pasar, la suite cae y hay que sacarlo de la
 * lista a mano, con su medición. Si un caso NUEVO cae, también cae
 * la suite: el residuo no crece en silencio.
 */
const RESIDUO_0197 = new Set(["matriz-a-006", "matriz-a-012", "matriz-a-018", "matriz-a-021", "matriz-a-024", "matriz-a-027", "matriz-a-033", "matriz-a-054", "matriz-a-055", "matriz-a-056", "matriz-a-057", "matriz-a-060", "matriz-a-066", "matriz-a-078", "matriz-a-081", "matriz-a-084", "matriz-a-087", "matriz-a-093", "matriz-a-097", "matriz-a-098", "matriz-a-099", "matriz-a-111", "matriz-a-114", "matriz-a-117", "matriz-a-120", "matriz-a-126", "matriz-a-130", "matriz-a-131", "matriz-a-132", "matriz-a-144", "matriz-a-147", "matriz-a-153", "matriz-a-159", "matriz-a-165", "matriz-a-177", "matriz-a-180", "matriz-a-183", "matriz-a-186", "matriz-a-192", "matriz-a-210", "matriz-a-213", "matriz-a-216", "matriz-a-219", "matriz-a-225", "matriz-a-243", "matriz-a-246", "matriz-a-249", "matriz-a-252", "matriz-a-258", "matriz-a-276", "matriz-a-279", "matriz-a-282", "matriz-a-285", "matriz-a-295", "matriz-a-296", "matriz-a-297", "matriz-a-303", "matriz-a-306", "matriz-a-309", "matriz-a-312", "matriz-a-318", "matriz-a-336", "matriz-a-339", "matriz-a-340", "matriz-a-341", "matriz-a-342", "matriz-a-345", "matriz-a-351", "matriz-a-363", "matriz-a-366", "matriz-a-369", "matriz-a-372", "matriz-a-378", "matriz-a-396", "matriz-a-399", "matriz-a-402", "matriz-a-411", "matriz-a-426", "matriz-a-429", "matriz-a-432", "matriz-a-438", "matriz-a-456", "matriz-a-459", "matriz-a-462", "matriz-a-463", "matriz-a-464", "matriz-a-465", "matriz-a-471", "matriz-a-477", "matriz-a-489", "matriz-a-492", "matriz-a-495", "matriz-a-498", "matriz-a-512", "matriz-a-524", "matriz-a-527"]);

function caso(c: CasoCaza) {
  (RESIDUO_0197.has(c.id) ? it.fails : it)(`${c.id} [${c.condicion}/${c.mutacion}] ${c.pregunta}`, () => {
    const r = verifyGroundedAnswer(c.respuesta, c.fuentes, c.idioma, c.pregunta);
    const presente = r.text.includes(c.marcador);
    let pasa: boolean;
    if (c.esperado === "corta") pasa = !presente;
    else if (c.esperado === "conserva") pasa = presente;
    else pasa = r.status === "skipped";
    RESULTADOS.push({
      ...c,
      obtenido: {
        status: r.status, removed: r.removed, kept: r.kept,
        marcadorPresente: presente,
        ...(c.esperado === "contrato-skipped" ? { payloadPresente: presente } : {}),
      },
      pasa,
    });
    expect(pasa, `esperado=${c.esperado} status=${r.status} removed=${r.removed} texto=${JSON.stringify(r.text.slice(0, 220))}`).toBe(true);
  });
}

afterAll(() => {
  try {
  writeFileSync("resultados-matriz-a.json", JSON.stringify(RESULTADOS, null, 1));
  } catch { /* El volcado de resultados es diagnóstico local: jamás es puerta, y en un entorno sin carpeta escribible (CI) no debe tumbar la batería. */ }
});

