    id: "matriz-a-220", eje: "matriz", dominio: "emergencias-terremoto",
    pregunta: "What should I do during an earthquake at home?", idioma: "en",
    condicion: "a", mutacion: "i", forma: null,
    fuentes: [{ title: "Earthquake safety", body: "During an earthquake, drop to the ground, take cover under a sturdy table and hold on. Do not run outside while the ground is still shaking. Stay away from windows and heavy furniture. After the shaking stops, wait 60 seconds before moving and call 911 if someone is hurt; the local information phone number is 800-555-0119. The local shelter stays open for 24 hours after a strong quake. This guide was reviewed on September 19, 2023." }],
    respuesta: "Drop to the ground, take cover under a sturdy table and hold on while the ground is shaking.",
