describe("matriz-a: matriz de dominios parte A", () => {
  for (const c of CASOS) caso(c);
});

describe("cobertura", () => {
  it("cada par condicion x mutacion (a/b/d) aparece >=2 veces en preguntas distintas", () => {
    const muts = ["i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x"];
    const faltas: string[] = [];
    for (const cond of ["a", "b", "d"]) {
      for (const mut of muts) {
        const qs = new Set(CASOS.filter((c) => c.condicion === cond && c.mutacion.split("-")[0] === mut).map((c) => c.pregunta));
        if (qs.size < 2) faltas.push(`${cond}/${mut}:${qs.size}`);
      }
    }
    expect(faltas).toEqual([]);
  });
  it("cada forma F-01..F-12 aparece >=2 veces en preguntas distintas", () => {
    const faltas: string[] = [];
    for (let n = 1; n <= 12; n++) {
      const f = `F-${String(n).padStart(2, "0")}`;
      const qs = new Set(CASOS.filter((c) => c.forma === f).map((c) => c.pregunta));
      if (qs.size < 2) faltas.push(`${f}:${qs.size}`);
    }
    expect(faltas).toEqual([]);
  });
});
